import com.koios.game.arpg.*;import com.koios.game.model.player.Player;import com.koios.game.model.item.Item;import com.koios.network.*;import com.koios.network.in.impl.PacketItemOption2;
public class TutorialEquipCheck{public static void main(String[] args)throws Exception{PrototypeIntegrationCheck.loaded();Player p=PrototypeIntegrationCheck.player("equipcheck",7);Tutorial.tick(p);p.setTeleporting(false);System.out.println("stage="+Tutorial.stage(p));for(int slot=0;slot<2;slot++){Item item=p.getInventory().get(slot);System.out.println("before slot"+slot+" id="+item.getId()+" type="+item.getDefinition().getEquipType()+" identified="+item.getRoll().isIdentified());GamePacket packet=new GamePacketBuilder(41).writeShort(item.getId()).writeShortA(slot).writeShortA(3214).toPacket();new PacketItemOption2().handle(p,packet);System.out.println("after equipped="+p.getEquipment().get(item.getDefinition().getEquipType().getSlot())+" inv="+p.getInventory().get(slot));}Tutorial.tick(p);System.out.println("stageAfter="+Tutorial.stage(p));MapRuns.cleanup(p);}}
